const precoUnitario = 49.9;
const quantidade = 3;
const taxaIva = 0.23;

const subtotal = precoUnitario * quantidade;

let valorIva = 0;
valorIva += subtotal * taxaIva;

const total = Number((subtotal + valorIva).toFixed(2));

console.log(subtotal); // 149.7
console.log(valorIva); // 34.431
console.log(total);    // 184.13

